import { chromium } from "playwright-core";
const S = "/workspace/hermes-mobile/dist/screens/"; const B = "http://localhost:8800";
const b = await chromium.launch({ executablePath: "/opt/google/chrome/chrome", args: ["--no-sandbox"] });
const ctx = await b.newContext({ viewport: { width: 412, height: 915 }, deviceScaleFactor: 2 });
const p = await ctx.newPage(); const errs = []; p.on("pageerror", (e) => errs.push(String(e)));
const vis = (loc) => loc.filter({ visible: true }).last();
await p.goto(B + "/bot/hermes"); await p.waitForTimeout(2500);
const box = vis(p.getByLabel("Ask Hermes")); await box.click(); await box.fill("half-written thought about the weekend trip");
await vis(p.getByLabel("Back to bots")).click(); await p.waitForTimeout(800);
await vis(p.getByLabel(/^Open Pi Ops/)).first().click(); await p.waitForTimeout(1200);
await vis(p.getByLabel("Back to bots")).click(); await p.waitForTimeout(800);
await vis(p.getByLabel(/^Open Hermes/)).first().click(); await p.waitForTimeout(1500);
console.log("in-app:", await vis(p.getByLabel("Ask Hermes")).inputValue());
await p.screenshot({ path: S + "61-draft-kept.png" });
await p.reload(); await p.waitForTimeout(3000);
console.log("after reload:", await vis(p.getByLabel("Ask Hermes")).inputValue());
console.log("pi-ops draft separate:", await (async () => { await p.goto(B + "/bot/pi-ops"); await p.waitForTimeout(2000); return JSON.stringify(await vis(p.getByLabel("Ask Pi Ops")).inputValue()); })());
console.log("errors:", errs); await b.close();
